import{_ as e,o,c as d,a2 as a}from"./chunks/framework.BZO4qERu.js";const b=JSON.parse('{"title":"Roo Code","description":"在 Roo Code 中选择 OpenAI Compatible Provider 接入 Tokeness。","frontmatter":{"title":"Roo Code","description":"在 Roo Code 中选择 OpenAI Compatible Provider 接入 Tokeness。"},"headers":[],"relativePath":"zh/integrations/roo-code.md","filePath":"zh/integrations/roo-code.md","lastUpdated":1783700215000}'),r={name:"zh/integrations/roo-code.md"};function i(l,t,n,s,h,p){return o(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="roo-code" tabindex="-1">Roo Code <a class="header-anchor" href="#roo-code" aria-label="Permalink to &quot;Roo Code&quot;">​</a></h1><p>Roo Code 是 VS Code 里的代码助手。它支持 <code>OpenAI Compatible</code> Provider，可以填写自定义 Base URL、API Key 和 Model ID。</p><h2 id="准备" tabindex="-1">准备 <a class="header-anchor" href="#准备" aria-label="Permalink to &quot;准备&quot;">​</a></h2><p>先在 Tokeness 控制台准备：</p><table tabindex="0"><thead><tr><th>项目</th><th>填写值</th></tr></thead><tbody><tr><td>Base URL</td><td><code>https://n.tokeness.io/v1</code></td></tr><tr><td>API Key</td><td>Tokeness 控制台创建的 Key</td></tr><tr><td>Model ID</td><td>从 Tokeness 模型广场复制完整模型名</td></tr></tbody></table><p>Roo Code 对工具调用依赖较强。用于编码任务时，优先选 Tokeness 中确认支持 OpenAI 工具调用的模型。</p><h2 id="新增-provider" tabindex="-1">新增 Provider <a class="header-anchor" href="#新增-provider" aria-label="Permalink to &quot;新增 Provider&quot;">​</a></h2><p>在 VS Code 中按下面配置：</p><ol><li>打开 Roo Code。</li><li>进入设置。</li><li>找到 API Provider。</li><li>选择 <code>OpenAI Compatible</code>。</li><li>在 Base URL 中填 <code>https://n.tokeness.io/v1</code>。</li><li>在 API Key 中填 Tokeness API Key。</li><li>在 Model 中填写从 Tokeness 模型广场复制的模型名。</li><li>保存配置。</li></ol><p>字段对应关系：</p><table tabindex="0"><thead><tr><th>Roo Code 字段</th><th>Tokeness 填写方式</th></tr></thead><tbody><tr><td>API Provider</td><td><code>OpenAI Compatible</code></td></tr><tr><td>Base URL</td><td><code>https://n.tokeness.io/v1</code></td></tr><tr><td>API Key</td><td>Tokeness API Key</td></tr><tr><td>Model / Model ID</td><td>Tokeness 模型名</td></tr></tbody></table><h2 id="模型配置" tabindex="-1">模型配置 <a class="header-anchor" href="#模型配置" aria-label="Permalink to &quot;模型配置&quot;">​</a></h2><p>如果 Roo Code 要求填写模型上下文或输出长度，可以先用保守值：</p><table tabindex="0"><thead><tr><th>配置项</th><th>说明</th></tr></thead><tbody><tr><td>Context Window</td><td>按 Tokeness 模型广场显示的上下文填写；不确定时先使用较小值</td></tr><tr><td>Max Output Tokens</td><td>首次测试可以填 2048 或 4096</td></tr><tr><td>Image Support</td><td>只有模型明确支持图片输入时再开启</td></tr><tr><td>Computer Use</td><td>只有当前模型和环境都支持时再开启</td></tr></tbody></table><p>不要一次打开所有高级能力。先让聊天和简单文件修改跑通，再逐步打开更复杂的能力。</p><h2 id="验证" tabindex="-1">验证 <a class="header-anchor" href="#验证" aria-label="Permalink to &quot;验证&quot;">​</a></h2><p>按下面顺序测试：</p><ol><li>新建一个临时文件。</li><li>让 Roo Code 解释一小段代码。</li><li>再让它修改这个临时文件。</li><li>在每一步后检查 Tokeness 使用日志。</li></ol><p>如果 Tokeness 日志里没有请求，说明 Roo Code 当前没有走 Tokeness Provider。回到设置页检查 Provider 是否保存成功。</p><h2 id="工具调用说明" tabindex="-1">工具调用说明 <a class="header-anchor" href="#工具调用说明" aria-label="Permalink to &quot;工具调用说明&quot;">​</a></h2><p>Roo Code 使用 OpenAI 原生工具调用格式。模型如果不支持工具调用，可能能回答普通问题，但无法稳定完成读文件、改文件、执行命令等任务。</p><p>遇到工具调用问题时，先做两个判断：</p><ol><li>同一个模型用普通 Chat Completions 是否能返回内容。</li><li>该模型是否支持 OpenAI 兼容的 tool calls。</li></ol><p>如果第一项成功、第二项失败，就换支持工具调用的模型，不要继续改 Base URL 或 Key。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>处理</th></tr></thead><tbody><tr><td>Invalid API Key</td><td>重新复制 Key，确认没有换行、空格或中文引号</td></tr><tr><td>Model Not Found</td><td>从 Tokeness 模型广场重新复制完整模型名</td></tr><tr><td>Connection Error</td><td>检查 Base URL 是否为 <code>https://n.tokeness.io/v1</code></td></tr><tr><td>普通聊天能用，文件操作失败</td><td>换支持工具调用的模型</td></tr><tr><td>输出中断</td><td>降低任务规模，或调高 Max Output Tokens</td></tr></tbody></table><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><ul><li><a href="https://docs.roocode.com/providers/openai-compatible" target="_blank" rel="noreferrer">Roo Code OpenAI Compatible Provider</a></li></ul>',28)])])}const k=e(r,[["render",i]]);export{b as __pageData,k as default};
